      { const L=[]; const cx=235, cz=135, n=17; for(let i=0;i<n;i++){ const t=i/(n-1)-.5, x=cx+t*110, hh=50-Math.abs(t)*70; for(const s of [-1,1]){ const g=new T.BoxGeometry(1.4,Math.max(12,hh),1.4); g.translate(0,Math.max(12,hh)/2,0); g.rotateX(s*(.62+Math.abs(t)*.5)); g.translate(x,0,cz); L.push(g); } } const sp=new T.BoxGeometry(110,2.4,4); sp.translate(cx,1.2,cz); L.push(sp); merge(L,WHT); }
      // 이웃 타워: 7 WTC(북, 226 m) · 3 WTC(329 m) · 4 WTC(298 m) · 브룩필드 플레이스 4동(웨스트 St 건너) · 윈터 가든
