      { const v=new T.CylinderGeometry(22,22,58,24,1,false,0,Math.PI); v.rotateZ(Math.PI/2); v.translate(-205,22,110); merge([v],K.col(0x9db4c2,{roughness:.1,metalness:.5,transparent:true,opacity:.8}),false); } // 윈터 가든 유리 볼트(개략)
      W.manh({x0:-900,x1:1400,z0:-1500,z1:1600,bx:120,bz:70,aw:16,sw:12,skip:(x,z,w,d)=>(x>-110&&x<330&&z>-200&&z<340)||(x>-60&&x<380&&z>=340&&z<560&&E.r()<.8)||x<-300,h:(x,z)=>{ const r=Math.hypot(x,z); let h=25+E.r()*E.r()*110; if(E.r()<.1) h=150+E.r()*100; if(r<520) h=Math.min(h,60+E.r()*60); return h; },gp:.55});
